operations.after:
word: $ => $.identifier,

// R reserved words (?Reserved) and the pipe placeholder `_` (R >= 4.2) are never
// identifiers: where the grammar does not expect them they are syntax errors (for
// example `x |> function(y) y` is not a call), and `_` is valid only where the
// grammar names it (`_placeholder`).
reserved: {
  global: $ => [
    'if', 'repeat', 'while', 'function', 'for', 'in', 'next', 'break',
    'TRUE', 'FALSE', 'NULL', 'Inf', 'NaN', 'NA', 'NA_integer_', 'NA_real_',
    'NA_complex_', 'NA_character_', '_'
  ]
},

operations.before:
    field("rhs", $._expression)
  ))))
},

// NOTE: Expression on LHS, string/identifier on RHS

operations.after:
    field("rhs", $._expression)
  ))),
  withPrec(PREC.SPECIAL_OR_PIPE, seq(
    field("lhs", $._expression),
    field("operator", "|>"),
    repeat($._newline),
    field("rhs", choice($.call, $._placeholder_chain))
  ))
)
},

// NOTE: Expression on LHS, string/identifier on RHS

operations.before:
if (valid_symbols[ERROR_SENTINEL]) {
  // Decline to handle when in "error recovery" mode. When a syntax error occurs,
  // tree-sitter calls the external scanner with all `valid_symbols` marked as valid.
  return false;
}

operations.after:
if (valid_symbols[ERROR_SENTINEL]) {
  // Decline to handle when in "error recovery" mode. When a syntax error occurs,
  // tree-sitter calls the external scanner with all `valid_symbols` marked as valid.
  // C2: except for a closing bracket that matches the innermost open scope. It stays a token, so
  // recovery can insert a MISSING operand before it (`(x <)`), and the scope closes, so newlines
  // after it separate statements again instead of being skipped as inside the bracket.
  consume_whitespace_and_ignored_newlines(lexer, scopes);
  Scope scope = scopes_peek(scopes);
  if (lexer->lookahead == ')' && scope == SCOPE_PAREN) {
    return scan_close_block(lexer, scopes, SCOPE_PAREN, CLOSE_PAREN);
  }
  if (lexer->lookahead == '}' && scope == SCOPE_BRACE) {
    return scan_close_block(lexer, scopes, SCOPE_BRACE, CLOSE_BRACE);
  }
  if (lexer->lookahead == ']' && scope == SCOPE_BRACKET) {
    return scan_close_block(lexer, scopes, SCOPE_BRACKET, CLOSE_BRACKET);
  }
  if (lexer->lookahead == ']' && scope == SCOPE_BRACKET2) {
    return scan_close_bracket2(lexer, scopes);
  }
  return false;
}
